parameters.jsCode:
// Compute week-over-week drop from Amplitude's two weekly buckets and decide if it crosses the per-account threshold.
// Amplitude segmentation with i=7 returns series values: [week_before, last_week] (oldest first).
const account = $('Batch Accounts (20/group)').item.json;
const payload = $json;

// Defensive extraction — Amplitude nests the series under data.series[0].
const series = payload?.data?.series?.[0] || [];
const weekBefore = Number(series[series.length - 2] ?? 0);
const lastWeek = Number(series[series.length - 1] ?? 0);

const threshold = Number(account.drop_threshold_pct ?? 40); // percent drop that triggers an alert
const minBaseline = Number(account.min_baseline_events ?? 10); // floor below which the account is too small to judge

let dropPct = 0;
let status = 'ok';
let reason = '';

if (weekBefore < minBaseline) {
  // Baseline too small — a swing from 2 to 1 active user is not a signal, it is noise.
  status = 'skipped_low_baseline';
  reason = `baseline ${weekBefore} actives below floor ${minBaseline}`;
} else {
  dropPct = Math.round(((weekBefore - lastWeek) / weekBefore) * 100);
  if (dropPct >= threshold) {
    status = 'alert';
    reason = `weekly actives fell ${dropPct}% (from ${weekBefore} to ${lastWeek}) vs the prior week`;
  } else if (dropPct > 0) {
    status = 'ok';
    reason = `down ${dropPct}% — under the ${threshold}% threshold`;
  } else {
    status = 'ok';
    reason = `flat or up (${weekBefore} -> ${lastWeek})`;
  }
}

return [{
  json: {
    account_id: account.account_id,
    account_name: account.account_name,
    csm_slack_user_id: account.csm_slack_user_id,
    segment: account.segment,
    last_alerted_at: account.last_alerted_at,
    week_before: weekBefore,
    last_week: lastWeek,
    drop_pct: dropPct,
    threshold,
    status,
    reason,
    checked_at: new Date().toISOString(),
  }
}];

