INSERT INTO usage_alert_history (
  account_id, alerted_at, week_before, last_week, drop_pct, threshold, reason
) VALUES ($1, now(), $2, $3, $4, $5, $6)
ON CONFLICT (account_id, date_trunc('week', alerted_at)) DO UPDATE SET
  week_before = EXCLUDED.week_before,
  last_week = EXCLUDED.last_week,
  drop_pct = EXCLUDED.drop_pct,
  threshold = EXCLUDED.threshold,
  reason = EXCLUDED.reason;

UPDATE accounts_in_scope SET last_alerted_at = now() WHERE account_id = $1;
